from typing import Optional

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class ConferenceResultsSchema(pydantic.BaseModel):
    conferenceUrl: pydantic.AnyHttpUrl
    conferenceId: Optional[str]
    conferencePin: Optional[str]


class ConferenceResponseSchema(BaseRapiResponseSchema):
    results: ConferenceResultsSchema
